// Catalogue data (generated by scripts/generate.mjs) and UI strings for both
// languages. German is served at the site root, English under /en/.
import de from '../generated/catalog.de.json';
import en from '../generated/catalog.en.json';

export type Lang = 'de' | 'en';
export type Catalog = typeof de;
export type Criterion = Catalog['criteria'][number];
export type Sub = Criterion['subs'][number];
export type Condition = Catalog['conditions']['items'][number];

export const LANGS: Lang[] = ['de', 'en'];
export const GC = 'GC';

const catalogs: Record<Lang, Catalog> = { de, en };

/** Path the site is served under: '' locally, '/c5catalogue' on GitHub Pages. */
export const base = import.meta.env.BASE_URL.replace(/\/+$/, '');

/** URL prefix of a language: base for German, base + '/en' for English. */
export const prefix = (lang: Lang) => base + (lang === 'en' ? '/en' : '');

/** The same page in the other language: /iam-06/ ↔ /en/iam-06/. */
export const switchLang = (path: string, to: Lang) => {
	const local = path.startsWith(base) ? path.slice(base.length) : path;
	const bare = local.replace(/^\/en(?=\/|$)/, '') || '/';
	return base + (to === 'en' ? `/en${bare === '/' ? '/' : bare}` : bare);
};

export function site(lang: Lang) {
	const data = catalogs[lang];
	const p = prefix(lang);
	const criteriaById = new Map(data.criteria.map((c) => [c.id, c]));
	const domains = [
		...data.domains.map((d) => ({ code: d.code, title: d.title, count: d.count })),
		{ code: GC, title: data.conditions.title, count: data.conditions.items.length },
	];
	return {
		lang,
		data,
		t: strings[lang],
		domains,
		criteriaById,
		criteriaIn: (code: string) => data.criteria.filter((c) => c.domain === code),
		domain: (code: string) => domains.find((d) => d.code === code),
		home: `${p}/`,
		info: `${p}/info/`,
		changes: `${p}/${strings[lang].changesPath}/`,
		domainUrl: (code: string) => `${p}/${code.toLowerCase()}/`,
		searchIndex: `${p}/search.json`,
	};
}
export type Site = ReturnType<typeof site>;

/** C5:2020 IDs a criterion replaces, unless it simply kept its own ID. */
export const predecessors = (c: Criterion) =>
	c.changes.old.length === 1 && c.changes.old[0] === c.id ? [] : c.changes.old;

const joinIds = (ids: string[], and: string) => (ids.length > 1 ? `${ids.slice(0, -1).join(', ')} ${and} ${ids.at(-1)}` : ids[0]);

