/**
 * Consecutive entries whose names share a theme ("Kapazitätsmanagement -
 * Planung", "Kapazitätsmanagement - Überwachung") are grouped under that theme
 * and keep the rest of their name as `short`. Everything else stays as is.
 */
export function groupByTheme<T extends { name: string }>(items: T[]) {
	type Row = T & { short: string };
	const themeOf = (name: string) => {
		const cut = name.indexOf(' - ');
		return cut > 0 ? name.slice(0, cut) : '';
	};
	const out: ({ theme: string; items: Row[] } | Row)[] = [];
	for (let i = 0; i < items.length; ) {
		const theme = themeOf(items[i].name);
		let j = i;
		while (j < items.length && theme && themeOf(items[j].name) === theme) j++;
		if (j - i >= 2) {
			out.push({ theme, items: items.slice(i, j).map((x) => ({ ...x, short: x.name.slice(theme.length + 3) })) });
			i = j;
		} else {
			out.push({ ...items[i], short: items[i].name });
			i++;
		}
	}
	return out;
}
